prompt = '''
You are an Assistant responsible for helping detect whether the retrieved document is relevant to the query. The query is a boolean search query, so you need to evaluate the document's relevance based on the conditions specified (e.g., "AND", "OR", "NOT").

Provide a relevance score from 0.0 to 100.0, where 100.0 indicates that the document strictly matches all conditions in the query, and 0.0 indicates no match. If uncertain, provide a score with one decimal place.

Query: {query}
Document: """{document}"""
Relevance score:
'''


def document_relevance(query, document):
    response = openai.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {
                "role": "system",
                "content": "You are an Assistant responsible for helping detect whether the retrieved document is relevant to the query. Output 'Yes' or 'No' indicating relevance.",
            },
            {"role": "user", "content": prompt.format(query=query, document=document)},
        ],
        temperature=0,
        logprobs=True,
        logit_bias={3363: 1, 1400: 1},
    )


